L["They were in your group and had not buffed you."] = "Estaba en tu grupo y no te había dado un beneficio."
L["They were not in your group and had not buffed you."] = "No estaba en tu grupo y no te había dado un beneficio."
L["They asked for it in chat."] = "Te lo pidió en el chat."
