L["Every title there is, and all of them earned. Nobody has better manners."] = "Todos los títulos que existen, y todos ganados. Nadie tiene mejores modales."
L["Title: %s -- %d of %d to %s"] = "Título: %s -- %d de %d para %s"
L["Title: %s -- every title earned"] = "Título: %s -- todos los títulos conseguidos"
