L["A new title for your manners: |cffffd100%s|r. %s"] = "Un nuevo título por tus modales: |cffffd100%s|r. %s"
L["Well Brought Up"] = "De buena crianza"
L["Somebody raised you right."] = "Se nota que te criaron bien."
L["Well Mannered"] = "De buenos modales"
L["You would hold the door, if dungeons had doors."] = "Cederías el paso en cada puerta, si las mazmorras tuvieran puertas."
L["Courteous"] = "Cortés"
L["Innkeepers have started to nod when you come in."] = "Los posaderos ya te saludan con la cabeza cuando entras."
L["Gracious"] = "Gentil"
L["You bow a little when you cast now. People have noticed."] = "Ahora te inclinas un poco al lanzar hechizos. La gente ya se fijó."
L["Magnanimous"] = "Noble de corazón"
L["Strangers argue over who gets to buff you first."] = "Los desconocidos se pelean por ser los primeros en darte un beneficio."
