L["What to cast"] = "Qué lanzar"
L["Buff to offer"] = "Beneficio que ofrecer"
L["You offer %s."] = "Ofreces %s."
L["%s is not offered to players without mana, such as warriors and rogues."] = "%s no se ofrece a jugadores sin maná, como guerreros y pícaros."
L["%s are not offered to players without mana, such as warriors and rogues."] = "%s no se ofrecen a jugadores sin maná, como guerreros y pícaros."
L["Nothing is ticked here, so the prompt will never appear."] = "No hay nada marcado aquí, así que el aviso nunca aparecerá."
